#include "stdlib/blas/base/zdotu.h"
#include "stdlib/blas/base/shared.h"

/**
* Calculates the dot product of two double-precision complex floating-point vectors using alternative indexing semantics.
*
* @param N        number of indexed elements
* @param X        first input array
* @param strideX  X stride length
* @param offsetX  starting index for X
* @param Y        second input array
* @param strideY  Y stride length
* @param offsetY  starting index for Y
* @param dot      output variable reference
*/
void API_SUFFIX(c_zdotu_ndarray)( const CBLAS_INT N, const void *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, const void *Y, const CBLAS_INT strideY, const CBLAS_INT offsetY, void *dot ) {
	const double *x = (const double *)X;
	const double *y = (const double *)Y;
	double *out = (double *)dot;
	CBLAS_INT sx;
	CBLAS_INT sy;
	CBLAS_INT ix;
	CBLAS_INT iy;
	CBLAS_INT i;
	double dr;
	double di;

	out[ 0 ] = 0.0;
	out[ 1 ] = 0.0;
	if ( N <= 0 ) {
		return;
	}
	sx = strideX * 2;
	sy = strideY * 2;
	ix = offsetX * 2;
	iy = offsetY * 2;

	dr = 0.0;
	di = 0.0;
	for ( i = 0; i < N; i++ ) {
		dr += ( x[ ix ] * y[ iy ] ) - ( x[ ix+1 ] * y[ iy+1 ] );
		di += ( x[ ix ] * y[ iy+1 ] ) + ( x[ ix+1 ] * y[ iy ] );
		ix += sx;
		iy += sy;
	}
	out[ 0 ] = dr;
	out[ 1 ] = di;
}
